--- completion_evidence {"type": "object", "additionalProperties": false, "required": ["policy", "status", "source", "completed_at", "reconciled_at", "evidence_refs"], "properties": {"policy": {"type": "string", "enum": ["manual", "linked_pr_merged_all", "linked_pr_merged_any", "issue_closed"]}, "status": {"type": "string", "enum": ["open", "in_progress", "blocked", "done", "not_applicable"]}, "source": {"type": ["string", "null"], "enum": [null, "github_pr_merge", "github_issue_close", "github_issue_reopen", "manual", "reconciliation"]}, "completed_at": {"type": ["string", "null"], "format": "date-time"}, "reconciled_at": {"type": ["string", "null"], "format": "date-time"}, "evidence_refs": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}}}}
