--- pull_request_linkages {"type": "array", "uniqueItems": true, "items": {"type": "object", "additionalProperties": false, "required": ["repo", "pr_number", "url", "base_branch", "head_branch", "state", "merged_at", "merge_commit_sha", "linked_at", "closing_reference_verified"], "properties": {"repo": {"type": "string", "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"}, "pr_number": {"type": "integer", "minimum": 1}, "url": {"type": "string", "format": "uri"}, "base_branch": {"type": "string", "minLength": 1}, "head_branch": {"type": "string", "minLength": 1}, "state": {"type": "string", "enum": ["open", "closed_unmerged", "merged"]}, "merged_at": {"type": ["string", "null"], "format": "date-time"}, "merge_commit_sha": {"type": ["string", "null"], "pattern": "^[0-9a-f]{40}$"}, "linked_at": {"type": "string", "format": "date-time"}, "closing_reference_verified": {"type": "boolean"}}}, "description": "task/IssueへlinkされたPR fact。closed_unmergedとmergedを分離し、default branch向けclosing referenceが確認できたmerged PRだけを自動完了evidenceに使う。"}

