#!/usr/bin/env python3
"""Independent macro audit of the C14 decomposition preview (read-only)."""
import json
import sys
from collections import defaultdict

payload = json.load(open(sys.argv[1], encoding="utf-8"))
nodes = payload["nodes"]
by_id = {n["graph_node_id"]: n for n in nodes}
report = {"violations": [], "checks": {}}


def fail(code, detail):
    report["violations"].append({"code": code, "detail": detail})


# 1. macro layer only: feature/architecture, no task granularity leakage
kinds = sorted({n["artifact_kind"] for n in nodes})
report["checks"]["kinds"] = kinds
for n in nodes:
    if n["artifact_kind"] not in {"feature", "architecture"}:
        fail("non_macro_kind", n["graph_node_id"])
    if n.get("phase_ref") is not None or n.get("feature_package_id") is not None or n.get("parent_feature") is not None:
        fail("phase_task_leakage", n["graph_node_id"])
report["checks"]["task_granularity_nodes"] = sum(1 for n in nodes if n["artifact_kind"] == "task")

# 2. inter-feature DAG acyclicity, independently recomputed via Kahn
indeg = {i: 0 for i in by_id}
adj = defaultdict(list)
for n in nodes:
    for dep in n["depends_on"]:
        if dep not in by_id:
            fail("dangling_dependency", f"{n['graph_node_id']}->{dep}")
            continue
        adj[dep].append(n["graph_node_id"])
        indeg[n["graph_node_id"]] += 1
queue = sorted([i for i, d in indeg.items() if d == 0])
order = []
while queue:
    cur = queue.pop(0)
    order.append(cur)
    for nxt in sorted(adj[cur]):
        indeg[nxt] -= 1
        if indeg[nxt] == 0:
            queue.append(nxt)
            queue.sort()
if len(order) != len(by_id):
    fail("dependency_cycle", f"topo_order={order}")
report["checks"]["topological_order"] = order
report["checks"]["inter_feature_edges"] = sorted(
    f"{n['graph_node_id']}->{d}" for n in nodes for d in n["depends_on"]
)

# 3. architecture_refs resolve to architecture nodes; features carry macro fields
for n in nodes:
    if n["artifact_kind"] == "feature":
        for field in ("purpose", "goal"):
            if not n.get(field):
                fail("feature_field_missing", f"{n['graph_node_id']}.{field}")
        for field in ("scope_in", "scope_out", "acceptance", "architecture_refs"):
            if not n.get(field):
                fail("feature_field_missing", f"{n['graph_node_id']}.{field}")
        for ref in n["architecture_refs"]:
            if by_id.get(ref, {}).get("artifact_kind") != "architecture":
                fail("architecture_ref_invalid", f"{n['graph_node_id']}->{ref}")

# 4. draft preview / no tracker projection eligibility
for n in nodes:
    if n["status"] != "draft" or n["confirmation_status"] != "draft" or n["evaluation_status"] != "pending":
        fail("not_draft_preview", n["graph_node_id"])
    if n["tracker_binding"] != "none":
        fail("tracker_binding_not_none", n["graph_node_id"])
    if n["github_publication"]["mode"] != "local_only":
        fail("publication_mode_not_local_only", n["graph_node_id"])
    if n["beads_linkage"] is not None or n["issue_linkage"] is not None:
        fail("unexpected_linkage", n["graph_node_id"])
    if n["github_project_linkages"] or n["pull_request_linkages"]:
        fail("unexpected_projection", n["graph_node_id"])
report["checks"]["publishable_nodes"] = [
    n["graph_node_id"] for n in nodes
    if n["confirmation_status"] == "confirmed"
    and n["evaluation_status"] == "pass"
    and n["implementation_readiness"]["status"] == "complete"
]

# 5. binding authority conflicts (mode=both+auto / github+local_only / beads+Issue)
config = json.load(open(sys.argv[2], encoding="utf-8"))
tracker_mode = config["execution_tracker"]["mode"]
report["checks"]["repo_tracker_mode"] = tracker_mode
report["checks"]["github_enabled"] = config["github"]["enabled"]
for n in nodes:
    b = n["tracker_binding"]
    m = n["github_publication"]["mode"]
    if b == "repo-config-default":
        fail("unresolved_binding", n["graph_node_id"])
    if tracker_mode == "both" and b == "repo-config-default":
        fail("mode_both_auto", n["graph_node_id"])
    if b == "github" and m == "local_only":
        fail("github_local_only", n["graph_node_id"])
    if b == "beads" and m != "local_only":
        fail("beads_issue_publication", n["graph_node_id"])

# 6. ready-feature package gate (macro-only run must register 0 packages)
ready = [
    n["graph_node_id"] for n in nodes
    if n["artifact_kind"] == "feature" and not n["depends_on"]
]
blocked = [
    n["graph_node_id"] for n in nodes
    if n["artifact_kind"] == "feature" and n["depends_on"]
]
report["checks"]["dependency_ready_features"] = ready
report["checks"]["dependency_blocked_features"] = blocked
report["checks"]["registered_packages"] = 0
report["checks"]["planner_invocations"] = 0

report["result"] = "PASS" if not report["violations"] else "FAIL"
print(json.dumps(report, ensure_ascii=False, indent=2))
sys.exit(0 if report["result"] == "PASS" else 1)

