    and n["implementation_readiness"]["status"] == "complete"
]

# 5. binding authority conflicts (mode=both+auto / github+local_only / beads+Issue)
config = json.load(open(sys.argv[2], encoding="utf-8"))
tracker_mode = config["execution_tracker"]["mode"]
report["checks"]["repo_tracker_mode"] = tracker_mode
report["checks"]["github_enabled"] = config["github"]["enabled"]
for n in nodes:
    b = n["tracker_binding"]
    m = n["github_publication"]["mode"]
    if b == "repo-config-default":
        fail("unresolved_binding", n["graph_node_id"])
    if tracker_mode == "both" and b == "repo-config-default":
        fail("mode_both_auto", n["graph_node_id"])
    if b == "github" and m == "local_only":
        fail("github_local_only", n["graph_node_id"])
    if b == "beads" and m != "local_only":
        fail("beads_issue_publication", n["graph_node_id"])

# 6. ready-feature package gate (macro-only run must register 0 packages)
ready = [
    n["graph_node_id"] for n in nodes
    if n["artifact_kind"] == "feature" and not n["depends_on"]
]
blocked = [
    n["graph_node_id"] for n in nodes
    if n["artifact_kind"] == "feature" and n["depends_on"]
]
report["checks"]["dependency_ready_features"] = ready
report["checks"]["dependency_blocked_features"] = blocked
report["checks"]["registered_packages"] = 0
report["checks"]["planner_invocations"] = 0

report["result"] = "PASS" if not report["violations"] else "FAIL"
print(json.dumps(report, ensure_ascii=False, indent=2))
sys.exit(0 if report["result"] == "PASS" else 1)

